# Notes are ordinary UTF-8 text files selected by the user.
from pathlib import Path


def note_save(app):
    # Cancel leaves the note and the filesystem unchanged.
    filename = filedialog.asksaveasfilename(parent=app.Form1, defaultextension=".txt", filetypes=[("Text files", "*.txt")])
    if not filename:
        return
    try:
        Path(filename).write_text(app.NoteText.get("1.0", "end-1c"), encoding="utf-8")
    except OSError as error:
        messagebox.showerror("Save note", str(error), parent=app.Form1)


def note_open(app):
    # Confirm before replacing the current text with an existing note.
    filename = filedialog.askopenfilename(parent=app.Form1, filetypes=[("Text files", "*.txt")])
    if not filename:
        return
    try:
        path = Path(filename)
        if path.stat().st_size > 2 * 1024 * 1024:
            raise ValueError("Notes are limited to 2 MiB.")
        text = path.read_text(encoding="utf-8-sig")
    except (OSError, UnicodeError, ValueError) as error:
        messagebox.showerror("Open note", str(error), parent=app.Form1)
        return
    if app.NoteText.get("1.0", "end-1c") and not messagebox.askyesno("Open note", "Replace the current note?", parent=app.Form1):
        return
    app.NoteText.delete("1.0", "end")
    app.NoteText.insert("1.0", text)


def note_color(app, color):
    # Change both the form and text background for a consistent sticky-note look.
    app.Form1.configure(bg=color)
    app.NoteText.configure(bg=color)


def note_close(app):
    # Ask before discarding a note; saving is always an explicit action.
    if not app.NoteText.get("1.0", "end-1c") or messagebox.askyesno("Close note", "Close this note without saving?", parent=app.Form1):
        app.root.destroy()
